using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using WudilFood.Data;
using WudilFood.Models;
using WudilFood.Services;
using WudilFood.ViewModels;
namespace WudilFood.Controllers;

[Authorize(Roles=Roles.Vendor)]
public class VendorController(AppDb db,IWebHostEnvironment environment):Controller
{
 static readonly HashSet<string> ImageExtensions=new(StringComparer.OrdinalIgnoreCase){".jpg",".jpeg",".png",".webp"}; string Uid=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 public async Task<IActionResult> Index(OrderState? state,string? q,Fulfillment? fulfillment,DateOnly? date){var v=await db.Vendors.Include(x=>x.Items).ThenInclude(x=>x.Schedules).FirstOrDefaultAsync(x=>x.UserId==Uid);if(v==null)return NotFound();var orders=db.Orders.AsNoTracking().Include(x=>x.Customer).Include(x=>x.Lines).Where(x=>x.VendorId==v.Id);if(state.HasValue)orders=orders.Where(x=>x.State==state);if(fulfillment.HasValue)orders=orders.Where(x=>x.Fulfillment==fulfillment);if(date.HasValue){var start=date.Value.ToDateTime(TimeOnly.MinValue,DateTimeKind.Local).ToUniversalTime();orders=orders.Where(x=>x.SlotUtc>=start&&x.SlotUtc<start.AddDays(1));}if(!string.IsNullOrWhiteSpace(q))orders=orders.Where(x=>EF.Functions.ILike(x.Reference,"%"+q+"%")||EF.Functions.ILike(x.Customer.FullName,"%"+q+"%"));ViewBag.Orders=await orders.OrderBy(x=>x.State==OrderState.Completed||x.State==OrderState.Cancelled).ThenBy(x=>x.SlotUtc).Take(100).ToListAsync();var done=db.Orders.AsNoTracking().Where(x=>x.VendorId==v.Id&&x.State==OrderState.Completed);ViewBag.CompletedCount=await done.CountAsync();ViewBag.Revenue=await done.SumAsync(x=>(decimal?)x.ItemsTotal)??0;var salesLines=await db.OrderLines.AsNoTracking().Where(x=>x.Order.VendorId==v.Id&&x.Order.State==OrderState.Completed).Select(x=>new{x.ItemName,x.Quantity,x.UnitPrice}).ToListAsync();ViewBag.TopItems=salesLines.GroupBy(x=>x.ItemName).Select(x=>new VendorProductStat(x.Key,x.Sum(y=>y.Quantity),x.Sum(y=>y.Quantity*y.UnitPrice))).OrderByDescending(x=>x.Quantity).Take(5).ToList();ViewBag.Closures=await db.VendorClosures.AsNoTracking().Where(x=>x.VendorId==v.Id&&x.EndsUtc>=DateTime.UtcNow).OrderBy(x=>x.StartsUtc).ToListAsync();ViewBag.SelectedState=state;ViewBag.Query=q;ViewBag.Fulfillment=fulfillment;ViewBag.Date=date;return View(v);}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Profile(string name,string description,string location,string operatingHours){var v=await db.Vendors.FirstOrDefaultAsync(x=>x.UserId==Uid);if(v==null)return NotFound();if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(location)||name.Length>120||location.Length>120||description?.Length>500||operatingHours?.Length>100)return BadRequest();v.Name=name.Trim();v.Description=description?.Trim()??"";v.Location=location.Trim();v.OperatingHours=operatingHours?.Trim()??"";await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Item(int? id){if(!await db.Vendors.AnyAsync(x=>x.UserId==Uid&&x.Status==ApprovalStatus.Approved))return RedirectToAction(nameof(Index));ViewBag.Categories=await db.Categories.OrderBy(x=>x.Name).ToListAsync();if(id==null){ViewBag.Schedules=new List<FoodSchedule>();return View(new ItemForm());}var item=await db.MenuItems.Include(x=>x.Schedules).FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid);if(item==null)return NotFound();ViewBag.Schedules=item.Schedules.OrderBy(x=>x.Day).ThenBy(x=>x.StartsAt).ToList();return View(new ItemForm{Id=item.Id,Name=item.Name,Description=item.Description,Price=item.Price,Stock=item.Stock,PreparationMinutes=item.PreparationMinutes,CategoryId=item.CategoryId,ExistingImages=item.ImageUrls.ToList(),ImageOrder=item.ImageUrls.ToList(),Mode=item.Mode,IsVisible=item.IsVisible});}
 [HttpPost,ValidateAntiForgeryToken,RequestSizeLimit(16_000_000)]public async Task<IActionResult> Item(ItemForm f){var vendor=await db.Vendors.FirstOrDefaultAsync(x=>x.UserId==Uid);if(vendor==null)return NotFound();if(vendor.Status!=ApprovalStatus.Approved)return Forbid();var item=f.Id>0?await db.MenuItems.Include(x=>x.Schedules).FirstOrDefaultAsync(x=>x.Id==f.Id&&x.VendorId==vendor.Id):null;if(f.Id>0&&item==null)return NotFound();var existing=item?.ImageUrls.ToList()??new();var ordered=f.ImageOrder.Where(existing.Contains).Distinct().ToList();ordered.AddRange(existing.Where(x=>!ordered.Contains(x)));var removed=ordered.Where(x=>f.RemoveImages.Contains(x)).ToList();var retained=ordered.Except(removed).ToList();var uploads=f.Images.Where(x=>x.Length>0).ToList();if(retained.Count+uploads.Count>3)ModelState.AddModelError(nameof(f.Images),"Each item can have no more than 3 images.");foreach(var file in uploads){var ext=Path.GetExtension(file.FileName);if(!ImageExtensions.Contains(ext)||!file.ContentType.StartsWith("image/",StringComparison.OrdinalIgnoreCase))ModelState.AddModelError(nameof(f.Images),$"{file.FileName} must be a JPG, PNG or WebP image.");if(file.Length>5_000_000)ModelState.AddModelError(nameof(f.Images),$"{file.FileName} is larger than 5 MB.");}if(!await db.Categories.AnyAsync(x=>x.Id==f.CategoryId)||!Enum.IsDefined(f.Mode))ModelState.AddModelError("","Invalid category or availability.");if(!ModelState.IsValid){f.ExistingImages=existing;ViewBag.Schedules=item?.Schedules.ToList()??new();ViewBag.Categories=await db.Categories.OrderBy(x=>x.Name).ToListAsync();return View(f);}var root=Path.Combine(environment.WebRootPath,"uploads","menu");Directory.CreateDirectory(root);var paths=new List<string>(retained);foreach(var file in uploads){var name=$"{Guid.NewGuid():N}{Path.GetExtension(file.FileName).ToLowerInvariant()}";await using var stream=System.IO.File.Create(Path.Combine(root,name));await file.CopyToAsync(stream);paths.Add($"/uploads/menu/{name}");}if(item==null){item=new MenuItem{VendorId=vendor.Id};db.MenuItems.Add(item);}item.Name=f.Name.Trim();item.Description=f.Description?.Trim()??"";item.Price=f.Price;item.Stock=f.Stock;item.PreparationMinutes=f.PreparationMinutes;item.CategoryId=f.CategoryId;item.ImageUrl=paths.Count==0?null:string.Join('|',paths);item.Mode=f.Mode;item.IsVisible=f.IsVisible;await db.SaveChangesAsync();foreach(var path in removed.Where(x=>x.StartsWith("/uploads/menu/"))){var physical=Path.Combine(root,Path.GetFileName(path));if(System.IO.File.Exists(physical))System.IO.File.Delete(physical);}return RedirectToAction(nameof(Item),new{id=item.Id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Schedule(int itemId,DayOfWeek day,TimeOnly startsAt,TimeOnly endsAt,TimeOnly orderDeadline,int? capacity){var item=await db.MenuItems.Include(x=>x.Schedules).FirstOrDefaultAsync(x=>x.Id==itemId&&x.Vendor.UserId==Uid&&x.Vendor.Status==ApprovalStatus.Approved);if(item==null)return NotFound();if(startsAt>=endsAt||orderDeadline>endsAt||capacity is <1||item.Schedules.Count>=14)return BadRequest("Check schedule times, capacity, or the 14-slot limit.");item.Schedules.Add(new FoodSchedule{Day=day,StartsAt=startsAt,EndsAt=endsAt,OrderDeadline=orderDeadline,Capacity=capacity});item.Mode=AvailabilityMode.Preorder;await db.SaveChangesAsync();return RedirectToAction(nameof(Item),new{id=itemId});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteSchedule(int id){var s=await db.FoodSchedules.FirstOrDefaultAsync(x=>x.Id==id&&x.MenuItem.Vendor.UserId==Uid);if(s==null)return NotFound();var itemId=s.MenuItemId;db.FoodSchedules.Remove(s);await db.SaveChangesAsync();return RedirectToAction(nameof(Item),new{id=itemId});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Closure(DateTime startsLocal,DateTime endsLocal,string? reason){var v=await db.Vendors.FirstOrDefaultAsync(x=>x.UserId==Uid&&x.Status==ApprovalStatus.Approved);if(v==null)return NotFound();if(startsLocal>=endsLocal||endsLocal<=DateTime.Now||endsLocal>startsLocal.AddDays(60)||reason?.Length>200)return BadRequest("Choose a valid closure of up to 60 days.");db.VendorClosures.Add(new VendorClosure{VendorId=v.Id,StartsUtc=startsLocal.ToUniversalTime(),EndsUtc=endsLocal.ToUniversalTime(),Reason=string.IsNullOrWhiteSpace(reason)?"Temporarily closed":reason.Trim()});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteClosure(int id){var c=await db.VendorClosures.FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid);if(c==null)return NotFound();db.VendorClosures.Remove(c);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> BulkStock(List<int> itemIds,List<int> stocks){if(itemIds.Count!=stocks.Count||stocks.Any(x=>x<0||x>100000))return BadRequest();var items=await db.MenuItems.Where(x=>itemIds.Contains(x.Id)&&x.Vendor.UserId==Uid).ToListAsync();if(items.Count!=itemIds.Distinct().Count())return Forbid();foreach(var item in items)item.Stock=stocks[itemIds.IndexOf(item.Id)];await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> SoldOut(int id){var item=await db.MenuItems.FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid);if(item==null)return NotFound();item.Stock=0;await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Duplicate(int id){var s=await db.MenuItems.AsNoTracking().Include(x=>x.Schedules).FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid&&x.Vendor.Status==ApprovalStatus.Approved);if(s==null)return NotFound();var copy=new MenuItem{VendorId=s.VendorId,CategoryId=s.CategoryId,Name=s.Name+" copy",Description=s.Description,Price=s.Price,Stock=0,PreparationMinutes=s.PreparationMinutes,ImageUrl=s.ImageUrl,IsVisible=false,Mode=s.Mode,Schedules=s.Schedules.Select(x=>new FoodSchedule{Day=x.Day,StartsAt=x.StartsAt,EndsAt=x.EndsAt,OrderDeadline=x.OrderDeadline,Capacity=x.Capacity}).ToList()};db.MenuItems.Add(copy);await db.SaveChangesAsync();return RedirectToAction(nameof(Item),new{id=copy.Id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Hide(int id){var item=await db.MenuItems.FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid);if(item==null)return NotFound();item.IsVisible=!item.IsVisible;await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AssignRider(int id,int riderId){var order=await db.Orders.Include(x=>x.Vendor).FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid);if(order==null)return NotFound();if(order.Fulfillment!=Fulfillment.Delivery||order.State is OrderState.Cancelled or OrderState.Completed)return BadRequest("A rider can only be assigned to an active delivery order.");var rider=await db.Riders.FirstOrDefaultAsync(x=>x.Id==riderId&&x.IsActive);if(rider==null)return BadRequest("Select an active rider.");order.RiderId=rider.Id;db.Notices.Add(new Notice{UserId=order.CustomerId,Text=$"{rider.Name} has been assigned to deliver order {order.Reference}. Contact: {rider.PhoneNumber}."});await db.SaveChangesAsync();return RedirectToAction("Details","Orders",new{id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> State(int id,OrderState state,string? returnTo=null){await using var tx=await db.Database.BeginTransactionAsync();var order=await db.Orders.Include(x=>x.Vendor).Include(x=>x.Lines).ThenInclude(x=>x.MenuItem).FirstOrDefaultAsync(x=>x.Id==id&&x.Vendor.UserId==Uid);if(order==null)return NotFound();if(order.Vendor.Status!=ApprovalStatus.Approved)return Forbid();if(state==OrderState.Shipped&&order.Fulfillment==Fulfillment.Delivery&&!order.RiderId.HasValue)return BadRequest("Assign a rider before marking this order as shipped.");if(!OrderWorkflow.CanTransition(order.State,state,order.Fulfillment))return BadRequest("Invalid order status change.");if(state==OrderState.Cancelled)OrderWorkflow.RestoreStock(order);order.State=state;db.Notices.Add(new Notice{UserId=order.CustomerId,Text=$"Order {order.Reference} is now {state}."});try{await db.SaveChangesAsync();await tx.CommitAsync();}catch(DbUpdateConcurrencyException){await tx.RollbackAsync();return Conflict("Stock changed while this order was being updated. Please retry.");}return returnTo=="vendor"?RedirectToAction(nameof(Index)):RedirectToAction("Details","Orders",new{id});}
}
public record VendorProductStat(string Name,int Quantity,decimal Revenue);
